# Generated by secure-by-design v0.1.0 for AI human-in-the-loop oversight.
# Aligns with ISO/IEC 42001 §8.3 and EU AI Act Art. 14 patterns.
# Reads from ../../privacy-security-manifest.yaml.
# Safe to modify. Safe to delete. Re-run /sbd-deploy to regenerate.
# Docs: docs/scaffolds/human_oversight.md
#
# For AI systems whose manifest declares humanOversight != 'none', any path
# from AI output → user-facing action MUST flow through this gate.

from __future__ import annotations

import dataclasses
from collections.abc import Mapping
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Any, Generic, Literal, Protocol, TypeVar, cast

from fastapi import HTTPException

from ..security.audit_log import audit_log

T = TypeVar('T')

OversightLevel = Literal['none', 'review-recommended', 'physician-review-mandatory', 'expert-review-mandatory']


@dataclass(frozen=True)
class OversightDecision:
    approver: str                  # identifier of the human who reviewed
    approver_role: str             # 'physician', 'specialist', 'compliance-officer', etc.
    decision: Literal['approved', 'rejected', 'modified']
    decided_at: datetime
    rationale: str | None = None   # free-text rationale (will be PHI-redacted in logs)
    modifications: Mapping[str, Any] | None = None  # when decision = 'modified'


@dataclass(frozen=True)
class ReviewRequest:
    system_name: str
    required_level: OversightLevel
    ai_output: Any
    data_principal_id: str | None = None


class OversightAdapter(Protocol):
    async def request_review(self, request: ReviewRequest) -> OversightDecision:
        """
        Request a human review. Implementation could be:
         - synchronous (block while a physician approves in UI)
         - asynchronous (queue + webhook callback)
         - in-line (physician is the actor and clicks "I approve")
        """
        ...


_adapter: OversightAdapter | None = None


def set_oversight_adapter(adapter: OversightAdapter) -> None:
    global _adapter
    _adapter = adapter


@dataclass(frozen=True)
class ReviewedOutput(Generic[T]):
    output: T
    decision: OversightDecision


class OversightRejectedError(HTTPException):
    code = 'OVERSIGHT_REJECTED'

    def __init__(self) -> None:
        super().__init__(status_code=451, detail='AI output rejected on human review.')


def _apply_modifications(output: T, modifications: Mapping[str, Any]) -> T:
    value = cast(Any, output)
    if isinstance(value, Mapping):
        return cast(T, {**value, **modifications})
    if dataclasses.is_dataclass(value) and not isinstance(value, type):
        return cast(T, dataclasses.replace(value, **modifications))
    if hasattr(value, 'model_copy'):
        return cast(T, value.model_copy(update=dict(modifications)))
    # The reviewer changed this output. Returning it unchanged would act on the unreviewed value.
    raise TypeError(f'secure-by-design: cannot apply review modifications to {type(output).__name__}.')


async def require_physician_review(
    system_name: str,
    ai_output: T,
    *,
    data_principal_id: str | None = None,
    level: OversightLevel = 'physician-review-mandatory',
) -> ReviewedOutput[T]:
    """
    Gate function — call after `decision_log(...)` returns AI output and before
    persisting / displaying / acting on it.

    Raises if no adapter is configured (this is intentional — production code
    with manifested humanOversight MUST have an adapter wired).
    """
    if level == 'none':
        return ReviewedOutput(
            output=ai_output,
            decision=OversightDecision(
                approver='system',
                approver_role='auto',
                decision='approved',
                decided_at=datetime.now(timezone.utc),
            ),
        )

    if _adapter is None:
        raise RuntimeError(
            f'secure-by-design: OversightAdapter not configured but oversight level is {level}. '
            'Either configure an adapter at boot or set the manifest aiSystems[].humanOversight to none.'
        )

    decision = await _adapter.request_review(ReviewRequest(
        system_name=system_name,
        required_level=level,
        ai_output=ai_output,
        data_principal_id=data_principal_id,
    ))

    await audit_log.security(
        f'ai.{system_name}.oversight',
        actor=decision.approver,
        target=data_principal_id,
        severity='NOTICE',
        outcome='denied' if decision.decision == 'rejected' else 'success',
        attrs={
            'level': level,
            'decision': decision.decision,
            'approver_role': decision.approver_role,
            'decided_at': decision.decided_at.isoformat(),
        },
    )

    if decision.decision == 'rejected':
        raise OversightRejectedError()

    if decision.decision == 'modified' and decision.modifications is not None:
        return ReviewedOutput(output=_apply_modifications(ai_output, decision.modifications), decision=decision)

    return ReviewedOutput(output=ai_output, decision=decision)
